// mfaEnv is the session harness with the TOTP key and a frozen clock, so a code
// generated by the test validates in the handler no matter when the suite runs.
type mfaEnv struct {
	*sessionEnv
	key []byte
	now time.Time
}

func newMFAEnv(t *testing.T) *mfaEnv {
	t.Helper()

	db := loginDB(t)
	cfg := loginConfig()
	signer, pub, raw := newLoginSigner(t, cfg)
	verifier := token.NewVerifier(cfg.Issuer, cfg.Audience, []token.PublicKey{{Kid: loginKid, Key: pub}})
	key, err := mfa.GenerateKey()
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	now := time.Now().UTC().Truncate(time.Second)

	h := newHarnessWithConfig(t, cfg, server.Deps{
		JWKS:     fakeJWKS{raw: raw},
		Signer:   signer,
		Verifier: verifier,
		Store:    db,
		MFAKey:   key,
		MFANow:   func() time.Time { return now },
	})
	return &mfaEnv{
		sessionEnv: &sessionEnv{h: h, db: db, cfg: cfg, signer: signer, pub: pub},
		key:        key,
		now:        now,
	}
}

// staff inserts an account and, when confirmed, gives it a confirmed TOTP factor. It
// returns the raw secret so the test can generate a matching code.
func (e *mfaEnv) staff(t *testing.T, roles []string, confirmed bool) (id, email, pw string, secret []byte) {
	t.Helper()

	email = uniqueLoginEmail("mfa")
	pw = "password-" + email
	id = insertStaff(t, e.db, email, "MFA Staff", pw, roles)
	if !confirmed {
		return id, email, pw, nil
	}

	secret, err := mfa.GenerateSecret()
	if err != nil {
		t.Fatalf("GenerateSecret: %v", err)
	}
	sealed, err := mfa.Seal(e.key, id, secret)
	if err != nil {
		t.Fatalf("Seal: %v", err)
	}
	if _, err := e.db.Pool.Exec(context.Background(),
		`UPDATE staff_user SET totp_secret_enc = $2, totp_confirmed_at = now() WHERE id = $1::uuid`,
		id, sealed); err != nil {
		t.Fatalf("confirm TOTP fixture: %v", err)
	}
	return id, email, pw, secret
}

// code returns the TOTP for secret on the env's frozen clock.
func (e *mfaEnv) code(secret []byte) string {
	return mfa.Code(secret, e.now, 6)
}

// postJSON sends one JSON request with an optional bearer.
func postJSON(t *testing.T, base, path, tok, body string) (int, http.Header, string) {
	t.Helper()

	req, err := http.NewRequest(http.MethodPost, base+path, strings.NewReader(body))
	if err != nil {
		t.Fatalf("NewRequest: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	if tok != "" {
		req.Header.Set("Authorization", "Bearer "+tok)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("POST %s: %v", path, err)
	}
	defer resp.Body.Close()
	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return resp.StatusCode, resp.Header, string(raw)
}

type mfaChallengeWire struct {
	MFARequired           bool   `json:"mfa_required"`
	MFAEnrollmentRequired bool   `json:"mfa_enrollment_required"`
	MFATicket             string `json:"mfa_ticket"`
	AccessToken           string `json:"access_token"`
}

type mfaEnrollWire struct {
	Secret     string `json:"secret"`
	OTPAuthURL string `json:"otpauth_url"`
}

type mfaConfirmWire struct {
	RecoveryCodes []string `json:"recovery_codes"`
	AccessToken   string   `json:"access_token"`
	ExpiresIn     int64    `json:"expires_in"`
	User          *struct {
		ID    string   `json:"id"`
		Name  string   `json:"name"`
		Roles []string `json:"roles"`
	} `json:"user"`
}

func decodeMFAChallenge(t *testing.T, body string) mfaChallengeWire {
	t.Helper()
	var got mfaChallengeWire
	if err := json.Unmarshal([]byte(body), &got); err != nil {
		t.Fatalf("challenge body %q is not JSON: %v", body, err)
	}
	return got
}

// loginTicket logs in and returns the challenge body.
func loginTicket(t *testing.T, e *mfaEnv, email, pw string) mfaChallengeWire {
	t.Helper()

	status, header, body := postLogin(t, e.h.public, fmt.Sprintf(`{"email":%q,"password":%q}`, email, pw))
	if status != http.StatusOK {
		t.Fatalf("login status = %d, want 200 (body %s)", status, body)
	}
	if set := header.Get("Set-Cookie"); set != "" {
		t.Fatalf("challenge login set a cookie: %q", set)
	}
	return decodeMFAChallenge(t, body)
}

// ticketPurpose reads one ticket's purpose straight from the database.
func ticketPurpose(t *testing.T, e *mfaEnv, ticket string) string {
	t.Helper()

	hash := sha256.Sum256([]byte(ticket))
	var purpose string
	if err := e.db.Pool.QueryRow(context.Background(),
		`SELECT purpose FROM mfa_ticket WHERE token_hash = $1`, hash[:]).Scan(&purpose); err != nil {
		t.Fatalf("read ticket purpose: %v", err)
	}
	return purpose
}

// insertRoot replaces any existing root with a fresh one and returns its id, email and
// a token. It mirrors the helper the user-management tests use.
func (e *mfaEnv) insertRoot(t *testing.T, pw string) (id, email string) {
	t.Helper()
	ctx := context.Background()

	_, _ = e.db.Pool.Exec(ctx, `DELETE FROM staff_invite WHERE created_by IN (SELECT id FROM staff_user WHERE is_root) OR user_id IN (SELECT id FROM staff_user WHERE is_root)`)
	_, _ = e.db.Pool.Exec(ctx, `DELETE FROM staff_user WHERE is_root`)

	hash, err := password.Hash(pw)
	if err != nil {
		t.Fatalf("password.Hash: %v", err)
	}
	email = uniqueLoginEmail("mfaroot")
	if err := e.db.Pool.QueryRow(ctx,
		`INSERT INTO staff_user (email, name, password_hash, roles, is_root)
		 VALUES ($1, $2, $3, ARRAY['admin'], true) RETURNING id::text`,
		email, "Root MFA", hash).Scan(&id); err != nil {
		t.Fatalf("insert root: %v", err)
	}
	t.Cleanup(func() {
		_, _ = e.db.Pool.Exec(context.Background(), `DELETE FROM staff_user WHERE id = $1::uuid`, id)
	})
	return id, email
}

func TestLoginRootWithConfirmedFactorStillGetsTokens(t *testing.T) {
	env := newMFAEnv(t)
	id, email := env.insertRoot(t, "root-password-1234")

	// Even a root that somehow has a confirmed factor is exempt.
	secret, _ := mfa.GenerateSecret()
	sealed, _ := mfa.Seal(env.key, id, secret)
	if _, err := env.db.Pool.Exec(t.Context(),
		`UPDATE staff_user SET totp_secret_enc = $2, totp_confirmed_at = now() WHERE id = $1::uuid`,
		id, sealed); err != nil {
		t.Fatalf("confirm root fixture: %v", err)
	}

	status, header, body := postLogin(t, env.h.public, fmt.Sprintf(`{"email":%q,"password":%q}`, email, "root-password-1234"))
	if status != http.StatusOK {
		t.Fatalf("root login status = %d, want 200 (body %s)", status, body)
	}
	if got := decodeLoginBody(t, body); got.AccessToken == "" {
		t.Error("root login returned no access token")
	}
	cookieFromHeader(t, header, testRefreshCookieName)
}

func TestLoginConfirmedFactorChallengesWithNoCookie(t *testing.T) {
	env := newMFAEnv(t)
	_, email, pw, _ := env.staff(t, []string{"live_ops"}, true)

	status, header, body := postLogin(t, env.h.public, fmt.Sprintf(`{"email":%q,"password":%q}`, email, pw))
	if status != http.StatusOK {
		t.Fatalf("status = %d, want 200 (body %s)", status, body)
	}
	if set := header.Get("Set-Cookie"); set != "" {
		t.Errorf("mfa_required login set a cookie: %q", set)
	}
	got := decodeMFAChallenge(t, body)
	if !got.MFARequired || got.MFAEnrollmentRequired {
		t.Errorf("challenge = %+v, want mfa_required only", got)
	}
	if got.MFATicket == "" {
		t.Error("mfa_ticket is empty")
	}
	if got.AccessToken != "" || strings.Contains(body, "access_token") {
		t.Error("the challenge body carries an access token")
	}
	if purpose := ticketPurpose(t, env, got.MFATicket); purpose != "verify" {
		t.Errorf("ticket purpose = %q, want verify", purpose)
	}
}

func TestLoginAdminWithoutTOTPRequiresEnrollment(t *testing.T) {
	env := newMFAEnv(t)
	id, email, pw, _ := env.staff(t, []string{"admin"}, false)

	// A password that was accepted must not clear the failure counter until a
	// session is actually issued.
	if _, err := env.db.Pool.Exec(t.Context(),
		`UPDATE staff_user SET failed_logins = 3 WHERE id = $1::uuid`, id); err != nil {
		t.Fatalf("seed failed_logins: %v", err)
	}

	got := loginTicket(t, env, email, pw)
	if !got.MFAEnrollmentRequired || got.MFARequired {
		t.Errorf("challenge = %+v, want mfa_enrollment_required only", got)
	}
	if purpose := ticketPurpose(t, env, got.MFATicket); purpose != "enroll" {
		t.Errorf("ticket purpose = %q, want enroll", purpose)
	}

	var failed int
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT failed_logins FROM staff_user WHERE id = $1::uuid`, id).Scan(&failed); err != nil {
		t.Fatalf("read failed_logins: %v", err)
	}
	if failed != 3 {
		t.Errorf("failed_logins = %d, want 3 (unchanged until a session is issued)", failed)
	}
}

