func TestMFAVerifyTOTPIssuesSession(t *testing.T) {
	env := newMFAEnv(t)
	id, email, pw, secret := env.staff(t, []string{"live_ops"}, true)

	ch := loginTicket(t, env, email, pw)
	status, header, body := postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, ch.MFATicket, env.code(secret)))
	if status != http.StatusOK {
		t.Fatalf("verify status = %d, want 200 (body %s)", status, body)
	}
	got := decodeLoginBody(t, body)
	if got.AccessToken == "" {
		t.Error("verify returned no access token")
	}
	if got.User.ID != id {
		t.Errorf("verify user id = %q, want %s", got.User.ID, id)
	}
	cookieFromHeader(t, header, testRefreshCookieName)

	var method string
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT details->>'mfa' FROM audit_log WHERE action = 'login.success' AND actor_id = $1 ORDER BY id DESC LIMIT 1`,
		id).Scan(&method); err != nil {
		t.Fatalf("read login.success details: %v", err)
	}
	if method != "totp" {
		t.Errorf("login.success mfa detail = %q, want totp", method)
	}
}

func TestMFAVerifyRejectsReplayedTOTP(t *testing.T) {
	env := newMFAEnv(t)
	_, email, pw, secret := env.staff(t, []string{"live_ops"}, true)
	code := env.code(secret)

	first := loginTicket(t, env, email, pw)
	if status, _, body := postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, first.MFATicket, code)); status != http.StatusOK {
		t.Fatalf("first verify status = %d, want 200 (body %s)", status, body)
	}

	second := loginTicket(t, env, email, pw)
	status, _, body := postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, second.MFATicket, code))
	if status != http.StatusUnauthorized {
		t.Fatalf("replay status = %d, want 401 (body %s)", status, body)
	}
	if got := decodeAPIError(t, body); got.Error.Code != "invalid_code" {
		t.Errorf("replay code = %q, want invalid_code", got.Error.Code)
	}
}

func TestMFAVerifyRecoveryCodeWorksOnce(t *testing.T) {
	env := newMFAEnv(t)
	id, email, pw, _ := env.staff(t, []string{"live_ops"}, true)

	codes, err := mfa.RecoveryCodes(3)
	if err != nil {
		t.Fatalf("RecoveryCodes: %v", err)
	}
	for _, code := range codes {
		if _, err := env.db.Pool.Exec(t.Context(),
			`INSERT INTO mfa_recovery_code (user_id, code_hash) VALUES ($1::uuid, $2)`,
			id, mfa.HashRecoveryCode(code)); err != nil {
			t.Fatalf("insert recovery code: %v", err)
		}
	}

	ch := loginTicket(t, env, email, pw)
	status, _, body := postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, ch.MFATicket, strings.ToUpper(codes[0])))
	if status != http.StatusOK {
		t.Fatalf("recovery verify status = %d, want 200 (body %s)", status, body)
	}
	got := decodeLoginBody(t, body)
	if got.AccessToken == "" {
		t.Error("recovery verify returned no access token")
	}

	var method string
	var remaining string
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT details->>'mfa' FROM audit_log WHERE action = 'login.success' AND actor_id = $1 ORDER BY id DESC LIMIT 1`,
		id).Scan(&method); err != nil {
		t.Fatalf("read login.success details: %v", err)
	}
	if method != "recovery_code" {
		t.Errorf("login.success mfa detail = %q, want recovery_code", method)
	}
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT details->>'remaining' FROM audit_log WHERE action = 'mfa.recovery_used' AND actor_id = $1 ORDER BY id DESC LIMIT 1`,
		id).Scan(&remaining); err != nil {
		t.Fatalf("read mfa.recovery_used details: %v", err)
	}
	if remaining != "2" {
		t.Errorf("remaining = %q, want 2", remaining)
	}

	// The same code cannot be used again, even on a fresh ticket.
	ch2 := loginTicket(t, env, email, pw)
	status, _, body = postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, ch2.MFATicket, codes[0]))
	if status != http.StatusUnauthorized {
		t.Fatalf("second recovery use status = %d, want 401 (body %s)", status, body)
	}
}

func TestMFAVerifyBurnsTicketAfterFiveWrongCodes(t *testing.T) {
	env := newMFAEnv(t)
	_, email, pw, secret := env.staff(t, []string{"live_ops"}, true)

	ch := loginTicket(t, env, email, pw)
	for i := 0; i < 5; i++ {
		status, _, body := postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
			fmt.Sprintf(`{"mfa_ticket":%q,"code":"000000"}`, ch.MFATicket))
		if status != http.StatusUnauthorized {
			t.Fatalf("wrong code %d status = %d, want 401 (body %s)", i+1, status, body)
		}
	}

	hash := sha256.Sum256([]byte(ch.MFATicket))
	var attempts int
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT failed_attempts FROM mfa_ticket WHERE token_hash = $1`, hash[:]).Scan(&attempts); err != nil {
		t.Fatalf("read ticket: %v", err)
	}
	if attempts != 5 {
		t.Errorf("failed_attempts = %d after five wrong codes, want 5", attempts)
	}

	// Even the right code no longer works on a burned ticket.
	status, _, body := postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, ch.MFATicket, env.code(secret)))
	if status != http.StatusUnauthorized {
		t.Fatalf("verify on a burned ticket = %d, want 401 (body %s)", status, body)
	}
	if got := decodeAPIError(t, body); got.Error.Code != "invalid_ticket" {
		t.Errorf("burned ticket code = %q, want invalid_ticket", got.Error.Code)
	}
}

