func TestMFAEnrollConfirmTicketFlow(t *testing.T) {
	env := newMFAEnv(t)
	id, email, pw, _ := env.staff(t, []string{"admin"}, false)

	ch := loginTicket(t, env, email, pw)
	if !ch.MFAEnrollmentRequired {
		t.Fatalf("login challenge = %+v, want mfa_enrollment_required", ch)
	}

	status, _, body := postJSON(t, env.h.public, "/admin-auth/mfa/enroll", "",
		fmt.Sprintf(`{"mfa_ticket":%q}`, ch.MFATicket))
	if status != http.StatusOK {
		t.Fatalf("enroll status = %d, want 200 (body %s)", status, body)
	}
	var enrolled mfaEnrollWire
	if err := json.Unmarshal([]byte(body), &enrolled); err != nil {
		t.Fatalf("enroll body %q is not JSON: %v", body, err)
	}
	if enrolled.Secret == "" || !strings.HasPrefix(enrolled.OTPAuthURL, "otpauth://totp/Otomo%20Admin:") {
		t.Errorf("enroll response = %+v, want a secret and otpauth URL", enrolled)
	}
	secret, err := mfa.DecodeSecret(enrolled.Secret)
	if err != nil {
		t.Fatalf("DecodeSecret: %v", err)
	}

	// The secret is stored sealed and still unconfirmed; the enroll ticket is not
	// consumed, so it can be used for the confirm step.
	var (
		sealed    []byte
		confirmed *time.Time
	)
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT totp_secret_enc, totp_confirmed_at FROM staff_user WHERE id = $1::uuid`, id).Scan(&sealed, &confirmed); err != nil {
		t.Fatalf("read pending secret: %v", err)
	}
	if confirmed != nil {
		t.Error("enroll set totp_confirmed_at")
	}
	if bytes.Contains(sealed, secret) {
		t.Error("the stored secret is not encrypted")
	}
	if purpose := ticketPurpose(t, env, ch.MFATicket); purpose != "enroll" {
		t.Errorf("ticket purpose = %q, want enroll", purpose)
	}

	status, header, body := postJSON(t, env.h.public, "/admin-auth/mfa/confirm", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, ch.MFATicket, env.code(secret)))
	if status != http.StatusOK {
		t.Fatalf("confirm status = %d, want 200 (body %s)", status, body)
	}
	var confirmedBody mfaConfirmWire
	if err := json.Unmarshal([]byte(body), &confirmedBody); err != nil {
		t.Fatalf("confirm body %q is not JSON: %v", body, err)
	}
	if len(confirmedBody.RecoveryCodes) != 10 {
		t.Errorf("recovery codes = %d, want 10", len(confirmedBody.RecoveryCodes))
	}
	if confirmedBody.AccessToken == "" || confirmedBody.User == nil || confirmedBody.User.ID != id {
		t.Errorf("confirm did not end signed in: %+v", confirmedBody)
	}
	cookieFromHeader(t, header, testRefreshCookieName)

	var (
		confirmedAt *time.Time
		recovery    int
		audits      int
	)
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT totp_confirmed_at FROM staff_user WHERE id = $1::uuid`, id).Scan(&confirmedAt); err != nil {
		t.Fatalf("read confirmed_at: %v", err)
	}
	if confirmedAt == nil {
		t.Error("totp_confirmed_at is still NULL after confirm")
	}
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT count(*) FROM mfa_recovery_code WHERE user_id = $1::uuid AND used_at IS NULL`, id).Scan(&recovery); err != nil {
		t.Fatalf("count recovery codes: %v", err)
	}
	if recovery != 10 {
		t.Errorf("live recovery codes = %d, want 10", recovery)
	}
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT count(*) FROM audit_log WHERE action = 'mfa.enroll' AND actor_id = $1`, id).Scan(&audits); err != nil {
		t.Fatalf("count mfa.enroll audits: %v", err)
	}
	if audits != 1 {
		t.Errorf("mfa.enroll audit rows = %d, want 1", audits)
	}

	// The ticket is single-use once confirmed.
	status, _, _ = postJSON(t, env.h.public, "/admin-auth/mfa/confirm", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, ch.MFATicket, env.code(secret)))
	if status != http.StatusUnauthorized {
		t.Errorf("second confirm with the same ticket = %d, want 401", status)
	}
}

func TestMFAEnrollConfirmViaBearer(t *testing.T) {
	env := newMFAEnv(t)
	id, _, _, _ := env.staff(t, []string{"viewer"}, false)
	tok, err := env.signer.Issue(id, "MFA Staff", []string{"viewer"}, env.now)
	if err != nil {
		t.Fatalf("Issue: %v", err)
	}

	status, _, body := postJSON(t, env.h.public, "/admin-auth/mfa/enroll", tok, `{}`)
	if status != http.StatusOK {
		t.Fatalf("bearer enroll status = %d, want 200 (body %s)", status, body)
	}
	var enrolled mfaEnrollWire
	if err := json.Unmarshal([]byte(body), &enrolled); err != nil {
		t.Fatalf("enroll body: %v", err)
	}
	secret, err := mfa.DecodeSecret(enrolled.Secret)
	if err != nil {
		t.Fatalf("DecodeSecret: %v", err)
	}

	status, header, body := postJSON(t, env.h.public, "/admin-auth/mfa/confirm", tok,
		fmt.Sprintf(`{"code":%q}`, env.code(secret)))
	if status != http.StatusOK {
		t.Fatalf("bearer confirm status = %d, want 200 (body %s)", status, body)
	}
	var confirmed mfaConfirmWire
	if err := json.Unmarshal([]byte(body), &confirmed); err != nil {
		t.Fatalf("confirm body: %v", err)
	}
	if len(confirmed.RecoveryCodes) != 10 {
		t.Errorf("recovery codes = %d, want 10", len(confirmed.RecoveryCodes))
	}
	// Bearer confirmation is the account page's flow: it does not mint a session
	// and must not set a refresh cookie.
	if confirmed.AccessToken != "" {
		t.Error("bearer confirm returned an access token")
	}
	if set := header.Get("Set-Cookie"); set != "" {
		t.Errorf("bearer confirm set a cookie: %q", set)
	}
}

