func TestMFASecretsAreSealedPerUser(t *testing.T) {
	env := newMFAEnv(t)
	idA, _, _, _ := env.staff(t, []string{"viewer"}, false)
	idB, _, _, _ := env.staff(t, []string{"viewer"}, false)

	sealFor := func(id string) []byte {
		t.Helper()
		secret, err := mfa.GenerateSecret()
		if err != nil {
			t.Fatalf("GenerateSecret: %v", err)
		}
		sealed, err := mfa.Seal(env.key, id, secret)
		if err != nil {
			t.Fatalf("Seal: %v", err)
		}
		if _, err := env.db.Pool.Exec(t.Context(),
			`UPDATE staff_user SET totp_secret_enc = $2 WHERE id = $1::uuid`, id, sealed); err != nil {
			t.Fatalf("store sealed secret: %v", err)
		}
		return sealed
	}
	sealedA := sealFor(idA)
	sealedB := sealFor(idB)

	if bytes.Equal(sealedA, sealedB) {
		t.Error("two users' ciphertexts are identical")
	}
	if _, err := mfa.Open(env.key, idA, sealedB); err == nil {
		t.Error("user B's ciphertext opened for user A")
	}
	if _, err := mfa.Open(env.key, idA, sealedA); err != nil {
		t.Errorf("user A's ciphertext did not open for user A: %v", err)
	}
}

func TestMFAMetricsSeriesArePreInitialised(t *testing.T) {
	env := newMFAEnv(t)

	body := metricsBody(t, env.h)
	for _, result := range []string{"verified", "recovery_code", "invalid_code", "invalid_ticket", "enrolled", "error"} {
		if got := counterValue(t, body, "staff_mfa_total", result); got != 0 {
			t.Errorf("staff_mfa_total{result=%q} = %v, want 0 before any request", result, got)
		}
	}
	for _, result := range []string{"mfa_required", "mfa_enrollment_required"} {
		if got := counterValue(t, body, "staff_login_total", result); got != 0 {
			t.Errorf("staff_login_total{result=%q} = %v, want 0 before any request", result, got)
		}
	}
}

func TestMFAMetricsAreCountedByOutcome(t *testing.T) {
	env := newMFAEnv(t)

	// invalid_ticket: an unknown ticket.
	postJSON(t, env.h.public, "/admin-auth/mfa/verify", "", `{"mfa_ticket":"no-such-ticket","code":"123456"}`)

	// verified and invalid_code for a confirmed account.
	_, email, pw, secret := env.staff(t, []string{"live_ops"}, true)
	badTicket := loginTicket(t, env, email, pw)
	postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":"000000"}`, badTicket.MFATicket))
	goodTicket := loginTicket(t, env, email, pw)
	postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, goodTicket.MFATicket, env.code(secret)))

	// enrolled: a full admin enrollment.
	_, adminEmail, adminPW, _ := env.staff(t, []string{"admin"}, false)
	ch := loginTicket(t, env, adminEmail, adminPW)
	_, _, enrollBody := postJSON(t, env.h.public, "/admin-auth/mfa/enroll", "",
		fmt.Sprintf(`{"mfa_ticket":%q}`, ch.MFATicket))
	var enrolled mfaEnrollWire
	if err := json.Unmarshal([]byte(enrollBody), &enrolled); err != nil {
		t.Fatalf("enroll body: %v", err)
	}
	adminSecret, _ := mfa.DecodeSecret(enrolled.Secret)
	postJSON(t, env.h.public, "/admin-auth/mfa/confirm", "",
		fmt.Sprintf(`{"mfa_ticket":%q,"code":%q}`, ch.MFATicket, env.code(adminSecret)))

	body := metricsBody(t, env.h)
	for result, want := range map[string]float64{
		"verified":       1,
		"recovery_code":  0,
		"invalid_code":   1,
		"invalid_ticket": 1,
		"enrolled":       1,
		"error":          0,
	} {
		if got := counterValue(t, body, "staff_mfa_total", result); got != want {
			t.Errorf("staff_mfa_total{result=%q} = %v, want %v", result, got, want)
		}
	}

	// The login metric set grew too: the challenge outcomes are counted there.
	login := metricsBody(t, env.h)
	if got := counterValue(t, login, "staff_login_total", "mfa_required"); got != 2 {
		t.Errorf("staff_login_total{mfa_required} = %v, want 2", got)
	}
	if got := counterValue(t, login, "staff_login_total", "mfa_enrollment_required"); got != 1 {
		t.Errorf("staff_login_total{mfa_enrollment_required} = %v, want 1", got)
	}
}

// TestMFAVerifyAttemptsAreBoundedUnderConcurrency: parallel guesses on one ticket must
// not get past the attempt limit, because each claims its attempt atomically before
// any code is checked.
func TestMFAVerifyAttemptsAreBoundedUnderConcurrency(t *testing.T) {
	env := newMFAEnv(t)
	_, email, pw, _ := env.staff(t, []string{"live_ops"}, true)
	ch := loginTicket(t, env, email, pw)

	const n = 20
	start := make(chan struct{})
	codes := make(chan string, n)
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			_, _, body := postJSON(t, env.h.public, "/admin-auth/mfa/verify", "",
				fmt.Sprintf(`{"mfa_ticket":%q,"code":"000000"}`, ch.MFATicket))
			codes <- decodeAPIError(t, body).Error.Code
		}()
	}
	close(start)
	wg.Wait()
	close(codes)

	counts := map[string]int{}
	for c := range codes {
		counts[c]++
	}
	if counts["invalid_code"] != 5 || counts["invalid_ticket"] != n-5 {
		t.Errorf("outcomes = %v, want exactly 5 invalid_code and %d invalid_ticket", counts, n-5)
	}
	hash := sha256.Sum256([]byte(ch.MFATicket))
	var attempts int
	if err := env.db.Pool.QueryRow(t.Context(),
		`SELECT failed_attempts FROM mfa_ticket WHERE token_hash = $1`, hash[:]).Scan(&attempts); err != nil {
		t.Fatalf("read ticket: %v", err)
	}
	if attempts != 5 {
		t.Errorf("failed_attempts = %d, want 5", attempts)
	}
}
